--[[
    HYDROGEN PRO V1 - NEON VIOLET BACKGROUND PATCH

    Launcher nay tai file style-only goc tu GitHub, thay anh nen nhung bang
    wallpaper neon tim moi, dieu chinh do toi va do trong suot cua panel,
    sau do chay lai source goc. Cac nut tab van giu mau do neon nhu anh mau.

    Luu y: source goc tiep tuc tai hub chinh tu CONFIG.SOURCE cua no.
    Chi chay neu ban tin tuong nguon ma ban dang su dung.
]]

local SOURCE_URL = "https://raw.githubusercontent.com/ntkdgaming1234qx-prog/SOLIEY-HUB/refs/heads/main/HYDROGEN_PRO_V1_style_only.lua"

-- Nen 16:9, nhan vat o ben trai va vung toi trong de khong che noi dung UI.
local BACKGROUND_JPEG_BASE64 = [=[]=]

local function fetchSource()
    local ok, source = pcall(function()
        return game:HttpGet(SOURCE_URL)
    end)
    if not ok or type(source) ~= "string" or #source < 10000 then
        warn("[HYDROGEN PATCH] Khong tai duoc source goc:", source)
        return nil
    end
    return source
end

local function replaceOnce(source, pattern, replacement, label)
    local changed, count = source:gsub(pattern, function()
        return replacement
    end, 1)
    if count ~= 1 then
        error("[HYDROGEN PATCH] Khong tim thay diem chen: " .. label)
    end
    return changed
end

local source = fetchSource()
if not source then return end

-- Lam panel de doc hon nhung van thay duoc anh nen.
source = replaceOnce(source, "MENU_TRANSPARENCY = 0%.35", "MENU_TRANSPARENCY = 0.27", "MENU_TRANSPARENCY")
source = replaceOnce(source, "BG_DARKEN = 0%.30", "BG_DARKEN = 0.18", "BG_DARKEN")

-- Tang nhe do sang vien tim cua cua so chinh; tab do neon duoc giu nguyen.
source = replaceOnce(source, "frameStroke%.Thickness = 2", "frameStroke.Thickness = 2.2", "main stroke thickness")
source = replaceOnce(source, "frameStroke%.Color = Color3%.fromRGB%(190, 55, 255%)", "frameStroke.Color = Color3.fromRGB(215, 75, 255)", "main stroke color")
source = replaceOnce(source, "ColorSequenceKeypoint%.new%(0, Color3%.fromRGB%(100, 35, 255%))", "ColorSequenceKeypoint.new(0, Color3.fromRGB(125, 35, 255))", "purple gradient start")
source = replaceOnce(source, "ColorSequenceKeypoint%.new%(0%.5, Color3%.fromRGB%(235, 45, 255%))", "ColorSequenceKeypoint.new(0.5, Color3.fromRGB(250, 80, 255))", "purple gradient center")

-- DATA la bien local ben trong source goc. Gan lai sau khi cac anh cu duoc khai bao,
-- nhung truoc start(), de prepareAssets() dung wallpaper moi.
local injection = "\n-- [HYDROGEN PATCH] Nen neon tim moi\nDATA.bg = [[" .. BACKGROUND_JPEG_BASE64 .. "]]\n"
source = replaceOnce(source, "start%(%)[%s]*$", injection .. "\nstart()", "final start() call")

local compiler = loadstring or load
if type(compiler) ~= "function" then
    warn("[HYDROGEN PATCH] Executor khong ho tro loadstring/load")
    return
end

local chunk, compileError = compiler(source)
if not chunk then
    warn("[HYDROGEN PATCH] Loi bien dich source:", compileError)
    return
end

local ok, runError = pcall(chunk)
if not ok then
    warn("[HYDROGEN PATCH] Loi khi chay source:", runError)
end
